(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zzd-sj-prepa-chir-j6-ide"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zzd-sj-prepa-chir-j6-ide\",\n \"titre\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 55,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J6_Chirurgie_IDE_corrige_explique.pdf\",\n   \"sha256\": \"0babcddc4f6493f9fd068b3c0945ab28f8575b9f70c9978e1eece0483b35d2d5\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Chirurgie · Prépa D.E J6 (IDE)\",\n     \"slug\": \"prepa-chir-j6-ide\",\n     \"pages\": \"\",\n     \"count\": 55,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Chirurgie\",\n     \"source\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__0\",\n       \"num\": \"1\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 1 : Vous êtes infirmier au centre de santé rural de GROHOUNFLA. M. ZAOULI, planteur, 60 ans, vous arrive à 3 h 00 du matin pour impossibilité brutale et totale d'uriner.\",\n       \"text\": \"À quelle pathologie pensez-vous ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rétention urinaire chronique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Adénome de la prostate\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Rétention urinaire aiguë\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Rétention urinaire aiguë\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La rétention aiguë (complète) se définit par l'impossibilité brutale et totale d'uriner : c'est exactement le tableau de M. ZAOULI (60 ans, à 3 h du matin). La rétention chronique est une impossibilité de vider totalement la vessie, d'installation progressive. L'adénome de la prostate est une cause possible, pas le diagnostic du tableau présenté.\\n\\nSource : licence 2 ide.pdf, Rétention urinaire, 1.1 Définition (p. 170) ; Cours de chirurgie traumatique et digestif.pptx, diapo 302\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__1\",\n       \"num\": \"2\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 1 : Vous êtes infirmier au centre de santé rural de GROHOUNFLA. M. ZAOULI, planteur, 60 ans, vous arrive à 3 h 00 du matin pour impossibilité brutale et totale d'uriner.\",\n       \"text\": \"Un signe physique parmi ceux énumérés ci-dessous vous conforte dans votre diagnostic ; lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Un globe vésical\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Besoin impérieux d'uriner\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Impossibilité d'uriner\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Un globe vésical\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les signes physiques de la rétention aiguë se trouvent au niveau du globe vésical : masse hypogastrique pouvant remonter jusqu'à l'ombilic, douloureuse à la palpation. Le besoin impérieux d'uriner et l'impossibilité d'uriner sont des signes fonctionnels (ressentis par le patient), pas des signes physiques.\\n\\nSource : licence 2 ide.pdf, Rétention urinaire, 1.2 Clinique (p. 170-171)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__2\",\n       \"num\": \"3\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 1 : Vous êtes infirmier au centre de santé rural de GROHOUNFLA. M. ZAOULI, planteur, 60 ans, vous arrive à 3 h 00 du matin pour impossibilité brutale et totale d'uriner.\",\n       \"text\": \"Un signe fonctionnel parmi ceux indiqués ci-dessous vous rassure pour le diagnostic posé, lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Globe vésical\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Douleur sous-pubienne plus ou moins intense à la palpation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Impossibilité d'uriner\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Impossibilité d'uriner\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'impossibilité d'uriner est le premier signe fonctionnel de la rétention aiguë, avec la douleur sus-pubienne de plus en plus intense. Le globe vésical est un signe physique ; la douleur « à la palpation » est aussi un signe d'examen (physique).\\n\\nSource : licence 2 ide.pdf, Rétention urinaire, 1.2.1 Signes fonctionnels (p. 170)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__3\",\n       \"num\": \"4\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 1 : Vous êtes infirmier au centre de santé rural de GROHOUNFLA. M. ZAOULI, planteur, 60 ans, vous arrive à 3 h 00 du matin pour impossibilité brutale et totale d'uriner.\",\n       \"text\": \"Un geste d'urgence peut immédiatement soulager M. ZAOULI ; lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Sondage urétral d'urgence\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Administration d'un antalgique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Intervention chirurgicale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Sondage urétral d'urgence\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le drainage vésical est une urgence ; la méthode citée en premier est le sondage urétral (ou, à défaut, la ponction sus-pubienne), dans le strict respect de l'asepsie. Il soulage immédiatement la distension. Un antalgique ne lève pas l'obstacle ; l'intervention chirurgicale relève du traitement étiologique, plus tard.\\n\\nSource : licence 2 ide.pdf, Rétention urinaire, 4. Traitement (p. 173-174)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__4\",\n       \"num\": \"5\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 1 : Vous êtes infirmier au centre de santé rural de GROHOUNFLA. M. ZAOULI, planteur, 60 ans, vous arrive à 3 h 00 du matin pour impossibilité brutale et totale d'uriner.\",\n       \"text\": \"La pose de la sonde urinaire se fait dans les cas suivants, sauf deux (02) ; lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rétention d'urines\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hypertrophie bénigne de la prostate\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Incontinence urinaire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Douleur sus-pubienne\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Infection urinaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. Douleur sus-pubienne ; E. Infection urinaire\",\n       \"answerLetters\": [\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Le sondage urinaire est indiqué dans la rétention d'urines (souvent par hypertrophie bénigne de la prostate) et dans l'incontinence. On ne sonde pas devant une infection urinaire (risque d'aggravation) ; une douleur sus-pubienne n'est pas en soi une indication. (explication hors cours du projet) en partie.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Rétention urinaire ; Traumatologie Complet-2.pdf, 8.2.4.1.9 (sonde si incontinence) IV. ÉTUDE DE CAS N°2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__5\",\n       \"num\": \"6\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 1 : Vous êtes infirmier au centre de santé rural de GROHOUNFLA. M. ZAOULI, planteur, 60 ans, vous arrive à 3 h 00 du matin pour impossibilité brutale et totale d'uriner.\",\n       \"text\": \"Dans la surveillance du patient avant la pose de la sonde urinaire, il faut procéder :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"À une hygiène des mains du praticien ou de son aide\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"À une préparation psychologique suivie de prévention d'escarres\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"À une réfection de lit occupé après toilette générale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"À un bain et douche quotidien du praticien au besoin\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"À une hygiène du méat, de la région génitale et rectale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. À une hygiène des mains du praticien ou de son aide ; E. À une hygiène du méat, de la région génitale et rectale\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\"\n       ],\n       \"explanation\": \"Le cours impose de « respecter rigoureusement les règles d'asepsie » lors du drainage vésical : cela passe par l'hygiène des mains du soignant (ou de son aide) et la toilette du méat, de la région génitale et périnéale avant la pose. Les autres propositions (prévention d'escarres, réfection du lit, douche du praticien) ne font pas partie de la préparation immédiate du sondage.\\n\\nSource : licence 2 ide.pdf, Rétention urinaire, 4. Traitement (N.B. asepsie, p. 174) — détail des gestes : explication en partie hors cours du projet\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__6\",\n       \"num\": \"7\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 1 : Vous êtes infirmier au centre de santé rural de GROHOUNFLA. M. ZAOULI, planteur, 60 ans, vous arrive à 3 h 00 du matin pour impossibilité brutale et totale d'uriner.\",\n       \"text\": \"L'un des objectifs visés dans la démarche de soins infirmiers, en cas de rétention urinaire, est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le retour du mode d'élimination normal des urines\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La pose de la sonde urinaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La ponction sus-pubienne\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Le retour du mode d'élimination normal des urines\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les objectifs de la démarche de soins sont le retour du mode d'élimination normal des urines et le soulagement de la douleur et des malaises. La pose de sonde et la ponction sus-pubienne sont des interventions (moyens), pas des objectifs.\\n\\nSource : licence 2 ide.pdf, Rétention urinaire, 5.3 Objectifs (p. 175)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__7\",\n       \"num\": \"8\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 1 : Vous êtes infirmier au centre de santé rural de GROHOUNFLA. M. ZAOULI, planteur, 60 ans, vous arrive à 3 h 00 du matin pour impossibilité brutale et totale d'uriner.\",\n       \"text\": \"Parmi les organes suivants, relever les deux organes qui constituent les organes de l'appareil urinaire haut.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La vessie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'urètre\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les reins\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les uretères\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La prostate\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Les reins ; D. Les uretères\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Le haut appareil urinaire comprend les reins (qui sécrètent l'urine) et les uretères (qui la conduisent vers la vessie). Vessie et urètre forment le bas appareil ; la prostate est une glande génitale. Le cours parle du « retentissement sur le haut appareil (distension des cavités, insuffisance rénale) ».\\n\\nSource : ANATOMIE LIVRE 2023-2024 OK.pdf, Chap. VI Appareil urinaire (p. 85) ; licence 2 ide.pdf, Rétention chronique, 2.2 (p. 171) — la répartition haut/bas est en partie hors cours du projet\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__8\",\n       \"num\": \"9\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 1 : Vous êtes infirmier au centre de santé rural de GROHOUNFLA. M. ZAOULI, planteur, 60 ans, vous arrive à 3 h 00 du matin pour impossibilité brutale et totale d'uriner.\",\n       \"text\": \"Relever les deux organes de l'appareil digestif haut parmi les organes suivants :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'œsophage\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le côlon\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La cavité buccale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'estomac\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'intestin grêle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. L'œsophage ; C. La cavité buccale\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Le tube digestif commence à la bouche et se termine à l'anus : cavité buccale, pharynx, œsophage, estomac, intestin grêle, côlon. La cavité buccale et l'œsophage en sont les premiers segments (partie haute, au-dessus du diaphragme). Le côlon et l'intestin grêle appartiennent au tube digestif bas. Remarque : Selon les auteurs, l'estomac est parfois rangé dans le « tube digestif haut » (endoscopie haute). Le sujet n'en retient que deux : cavité buccale et œsophage.\\n\\nSource : PDF APPAREIL DIGESTIF L1 SF IDE 2023.pdf, I. Anatomie du tube digestif ; ANATOMIE LIVRE 2023-2024 OK.pdf, Chap. IV (p. 64)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__9\",\n       \"num\": \"10\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 1 : Vous êtes infirmier au centre de santé rural de GROHOUNFLA. M. ZAOULI, planteur, 60 ans, vous arrive à 3 h 00 du matin pour impossibilité brutale et totale d'uriner.\",\n       \"text\": \"L'urine est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"un liquide jaune, clair, limpide\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"un liquide jaune pâle, clair, trouble\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"un liquide jaune pâle, clair, limpide\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. un liquide jaune pâle, clair, limpide\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'urine normale est habituellement de couleur jaune (pigment : l'urochrome) ; fraîchement émise, elle est claire et limpide. Une urine trouble évoque une anomalie (infection, dépôts).\\n\\nSource : ANATOMIE LIVRE 2023-2024 OK.pdf, Physiologie de l'appareil urinaire, caractéristiques physiques (p. 91) — « pâle, clair, limpide » : précision hors cours du projet\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__10\",\n       \"num\": \"11\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 1 : Vous êtes infirmier au centre de santé rural de GROHOUNFLA. M. ZAOULI, planteur, 60 ans, vous arrive à 3 h 00 du matin pour impossibilité brutale et totale d'uriner.\",\n       \"text\": \"Chez l'homme, l'urètre mesure environ :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"24 cm\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"14 cm\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"04 cm\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 14 cm\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Chez l'homme, l'urètre mesure en moyenne de 10 à 16 cm (canal excréteur de la vessie, jusqu'au méat du gland) ; 14 cm est dans cet intervalle. Chez la femme, il ne dépasse pas 3 à 4 cm. Remarque : Le cours de chirurgie (Rétrécissement de l'urètre) donne 10 à 12 cm ; le livre d'anatomie donne 10 à 16 cm. La réponse 14 cm correspond au livre d'anatomie.\\n\\nSource : ANATOMIE LIVRE 2023-2024 OK.pdf, Chap. VI, L'urètre (p. 89)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__11\",\n       \"num\": \"12\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 1 : Vous êtes infirmier au centre de santé rural de GROHOUNFLA. M. ZAOULI, planteur, 60 ans, vous arrive à 3 h 00 du matin pour impossibilité brutale et totale d'uriner.\",\n       \"text\": \"L'anurie se caractérise par :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une grande quantité d'urine\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une absence d'urine\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une petite quantité d'urine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Une absence d'urine\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'anurie est l'absence (ou quasi-absence) d'émission d'urines par arrêt de leur production. Une petite quantité d'urine correspond à l'oligurie ; une grande quantité à la polyurie.\\n\\nSource : (explication hors cours du projet) — le cours de sémiologie emploie le terme « anurie » dans les complications des brûlures, sans le définir.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__12\",\n       \"num\": \"13\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 1 : Vous êtes infirmier au centre de santé rural de GROHOUNFLA. M. ZAOULI, planteur, 60 ans, vous arrive à 3 h 00 du matin pour impossibilité brutale et totale d'uriner.\",\n       \"text\": \"La diurèse normale de 24 heures est de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"800 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1500 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"1000 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 1500 ml\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les reins filtrent environ 180 L par 24 h, mais 99 % sont réabsorbés : l'élimination urinaire est d'environ 1 ml/min, soit 1,5 L (1500 ml) par 24 h.\\n\\nSource : ANATOMIE LIVRE 2023-2024 OK.pdf, 3.1.1 Filtration glomérulaire et 3.1.2 Réabsorption tubulaire (p. 89)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__13\",\n       \"num\": \"14\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 1 : Vous êtes infirmier au centre de santé rural de GROHOUNFLA. M. ZAOULI, planteur, 60 ans, vous arrive à 3 h 00 du matin pour impossibilité brutale et totale d'uriner.\",\n       \"text\": \"La rétention urinaire chronique est dite rétention avec distension lorsque le volume du résidu post-mictionnel est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Supérieur à 300 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Égal à 300 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Inférieur à 300 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Supérieur à 300 ml\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Si le résidu post-mictionnel est supérieur à 300 cc, on parle de rétention avec distension ; s'il est inférieur à 300 cc, de rétention sans distension.\\n\\nSource : licence 2 ide.pdf, Rétention chronique, 2.1 Définition (p. 171) ; Cours de chirurgie traumatique et digestif.pptx, diapo 303\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__14\",\n       \"num\": \"15\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 1 : Vous êtes infirmier au centre de santé rural de GROHOUNFLA. M. ZAOULI, planteur, 60 ans, vous arrive à 3 h 00 du matin pour impossibilité brutale et totale d'uriner.\",\n       \"text\": \"Parmi les signes suivants, relever le signe fonctionnel de la rétention chronique d'urine :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"De quelques gouttes d'urines\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Impossibilité d'uriner\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Besoin impérieux d'uriner permanent devenant douloureux et n'aboutissant au mieux qu'à l'émission\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Impossibilité de vider totalement la vessie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Impossibilité de vider totalement la vessie\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La rétention chronique se traduit par l'impossibilité de vider totalement la vessie (existence d'un résidu post-mictionnel). Les autres propositions (impossibilité totale d'uriner, besoin impérieux n'aboutissant qu'à quelques gouttes) décrivent la rétention aiguë. Remarque : Dans le cours, « impossibilité de vider totalement la vessie » est la définition ; les signes fonctionnels listés sont la pollakiurie et l'incontinence par regorgement (absents des options).\\n\\nSource : licence 2 ide.pdf, Rétention chronique, 2.1 et 2.3.1 (p. 171-172)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__15\",\n       \"num\": \"16\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 1 : Vous êtes infirmier au centre de santé rural de GROHOUNFLA. M. ZAOULI, planteur, 60 ans, vous arrive à 3 h 00 du matin pour impossibilité brutale et totale d'uriner.\",\n       \"text\": \"Relever parmi les examens biologiques suivants les trois qui peuvent être demandés à un patient porteur d'un adénome de la prostate.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"URÉE\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"PSA\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"NFS\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"GE\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"ECBU\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. URÉE ; B. PSA ; E. ECBU\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"En cas d'adénome de la prostate, le cours demande : urée, créatinine (fonction rénale), ECBU (recherche d'infection) et dosage du PSA (évolution de la prostate). NFS et GE ne font pas partie de ce bilan spécifique (la NFS entre seulement dans le bilan préopératoire).\\n\\nSource : licence 2 ide.pdf, Adénome de la prostate, 3.3.1 Biologie (p. 163) ; Cours de chirurgie traumatique et digestif.pptx, diapo 290\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__16\",\n       \"num\": \"17\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 1 : Vous êtes infirmier au centre de santé rural de GROHOUNFLA. M. ZAOULI, planteur, 60 ans, vous arrive à 3 h 00 du matin pour impossibilité brutale et totale d'uriner.\",\n       \"text\": \"Parmi les signes suivants, relever les deux signes physiques de la rétention aiguë d'urine :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Douleur à la palpation augmentant le besoin d'uriner\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Globe vésical flaccide parfois énorme de 2 à 3 litres et indolore\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Impossibilité d'uriner\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Douleur sus-pubienne de plus en plus intense\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Masse hypogastrique pouvant remonter jusqu'à l'ombilic\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Douleur à la palpation augmentant le besoin d'uriner ; E. Masse hypogastrique pouvant remonter jusqu'à l'ombilic\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\"\n       ],\n       \"explanation\": \"Signes physiques de la rétention aiguë (au niveau du globe vésical) : une masse hypogastrique pouvant remonter jusqu'à l'ombilic et une douleur à la palpation augmentant le besoin d'uriner. Le globe flaccide, indolore, de 2 à 3 L appartient à la rétention chronique ; l'impossibilité d'uriner et la douleur sus-pubienne sont des signes fonctionnels.\\n\\nSource : licence 2 ide.pdf, Rétention urinaire, 1.2.2 Signes physiques et 2.3.2 (p. 171-172)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__17\",\n       \"num\": \"18\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 2 : Vous recevez Mademoiselle Daména, âgée de 27 ans, pesant 90 kg, victime d'un accident avec collision de deux véhicules. L'examen est sans lésion corporelle externe ; on note une douleur abdominale, une tachypnée superficielle, une tension artérielle basse, une soif intense, des sueurs froides profuses et un bombement du cul-de-sac de Douglas au toucher rectal. Face à ces différents signes, le chirurgien pose le diagnostic de contusion abdominale.\",\n       \"text\": \"Quelle définition accordez-vous à la contusion abdominale ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Traumatisme de l'abdomen avec solution de continuité profonde\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Traumatisme de l'abdomen avec lésion costale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Traumatisme de l'abdomen sans solution de continuité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Traumatisme de l'abdomen avec mise en évidence des viscères\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Traumatisme de l'abdomen sans solution de continuité\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les contusions de l'abdomen sont des traumatismes de l'abdomen sans solution de continuité de la paroi abdominale : ce sont des traumatismes fermés. Une solution de continuité ou une éviscération définit une plaie de l'abdomen.\\n\\nSource : licence 2 ide.pdf, Contusions abdominales, Introduction (p. 89)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__18\",\n       \"num\": \"19\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 2 : Vous recevez Mademoiselle Daména, âgée de 27 ans, pesant 90 kg, victime d'un accident avec collision de deux véhicules. L'examen est sans lésion corporelle externe ; on note une douleur abdominale, une tachypnée superficielle, une tension artérielle basse, une soif intense, des sueurs froides profuses et un bombement du cul-de-sac de Douglas au toucher rectal. Face à ces différents signes, le chirurgien pose le diagnostic de contusion abdominale.\",\n       \"text\": \"Les signes observés chez dame Daména vous font évoquer quel tableau ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Tableau d'abdomen contus apparemment normal\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Tableau de péritonite par perforation d'organe creux\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Tableau d'hémopéritoine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Tableau d'hémopéritoine\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Daména présente des signes de choc par hémorragie interne (tension basse, soif intense, sueurs froides, tachypnée superficielle) et des signes d'épanchement intrapéritonéal (bombement du Douglas) : c'est le tableau d'hémopéritoine. La péritonite par perforation donne surtout contracture (« ventre de bois »), vomissements et pneumopéritoine. Remarque : Dans le sujet, l'option s'affiche « Option 2Tableau d'hémopéritoine » (reste de saisie).\\n\\nSource : licence 2 ide.pdf, Contusions abdominales, II. Signes, 2.1 et 2.2 (p. 90-91)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__19\",\n       \"num\": \"20\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 2 : Vous recevez Mademoiselle Daména, âgée de 27 ans, pesant 90 kg, victime d'un accident avec collision de deux véhicules. L'examen est sans lésion corporelle externe ; on note une douleur abdominale, une tachypnée superficielle, une tension artérielle basse, une soif intense, des sueurs froides profuses et un bombement du cul-de-sac de Douglas au toucher rectal. Face à ces différents signes, le chirurgien pose le diagnostic de contusion abdominale.\",\n       \"text\": \"Quels sont les deux signes évocateurs d'un état de choc chez madame Daména ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une soif intense\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Un bombement du cul-de-sac de Douglas\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Des sueurs froides profuses\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une douleur abdominale\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Une tachypnée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Une soif intense ; C. Des sueurs froides profuses\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Parmi les signes de choc hypovolémique, le cours cite la soif intense et les sueurs froides profuses (avec extrémités froides, pouls filant, TA basse). La tachypnée superficielle est classée dans les signes d'anémie aiguë ; le bombement du Douglas et la douleur abdominale traduisent l'épanchement et l'irritation péritonéale.\\n\\nSource : licence 2 ide.pdf, Contusions abdominales, 2.1 Tableau d'hémopéritoine (p. 91)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__20\",\n       \"num\": \"21\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 2 : Vous recevez Mademoiselle Daména, âgée de 27 ans, pesant 90 kg, victime d'un accident avec collision de deux véhicules. L'examen est sans lésion corporelle externe ; on note une douleur abdominale, une tachypnée superficielle, une tension artérielle basse, une soif intense, des sueurs froides profuses et un bombement du cul-de-sac de Douglas au toucher rectal. Face à ces différents signes, le chirurgien pose le diagnostic de contusion abdominale.\",\n       \"text\": \"Le chirurgien suspecte la rupture de viscères pleins, lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Duodénum\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Iléon\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Jéjunum\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Foie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Rate\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Estomac\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. Foie ; E. Rate\",\n       \"answerLetters\": [\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Les viscères pleins sont le foie, la rate, les reins (et le pancréas) ; leur lésion donne un hémopéritoine. Duodénum, iléon, jéjunum et estomac sont des organes creux dont la rupture donne une péritonite.\\n\\nSource : licence 2 ide.pdf, Contusions abdominales, 1.2 Conséquences anatomiques (p. 90) ; Cours de chirurgie traumatique et digestif.pptx, diapo 184\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__21\",\n       \"num\": \"22\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 2 : Vous recevez Mademoiselle Daména, âgée de 27 ans, pesant 90 kg, victime d'un accident avec collision de deux véhicules. L'examen est sans lésion corporelle externe ; on note une douleur abdominale, une tachypnée superficielle, une tension artérielle basse, une soif intense, des sueurs froides profuses et un bombement du cul-de-sac de Douglas au toucher rectal. Face à ces différents signes, le chirurgien pose le diagnostic de contusion abdominale.\",\n       \"text\": \"Quel signe présenté par Daména permet de confirmer l'épanchement liquidien intrapéritonéal ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une tachypnée superficielle\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Un bombement du cul-de-sac de Douglas au toucher rectal\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une tension artérielle basse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une douleur abdominale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Un bombement du cul-de-sac de Douglas au toucher rectal\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les signes d'épanchement liquidien intrapéritonéal sont la matité déclive des flancs et le bombement du cul-de-sac de Douglas au toucher rectal. La TA basse et la tachypnée sont des signes de choc et d'anémie ; la douleur abdominale est non spécifique.\\n\\nSource : licence 2 ide.pdf, Contusions abdominales, 2.1 (p. 91)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__22\",\n       \"num\": \"23\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 2 : Vous recevez Mademoiselle Daména, âgée de 27 ans, pesant 90 kg, victime d'un accident avec collision de deux véhicules. L'examen est sans lésion corporelle externe ; on note une douleur abdominale, une tachypnée superficielle, une tension artérielle basse, une soif intense, des sueurs froides profuses et un bombement du cul-de-sac de Douglas au toucher rectal. Face à ces différents signes, le chirurgien pose le diagnostic de contusion abdominale.\",\n       \"text\": \"À l'examen physique de Daména, la palpation recherche les deux signes suivants. Lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Recherche des lésions cutanées\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une matité déclive des flancs\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un tympanisme diffus ou localisé\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Des points douloureux exquis\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Une défense localisée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. Des points douloureux exquis ; E. Une défense localisée\",\n       \"answerLetters\": [\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"À l'examen physique, la palpation recherche des points douloureux exquis, une défense localisée et une douleur provoquée. La recherche de lésions cutanées relève de l'inspection ; la matité déclive des flancs et le tympanisme relèvent de la percussion.\\n\\nSource : licence 2 ide.pdf, Contusions abdominales, Examen physique (p. 92)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__23\",\n       \"num\": \"24\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 2 : Vous recevez Mademoiselle Daména, âgée de 27 ans, pesant 90 kg, victime d'un accident avec collision de deux véhicules. L'examen est sans lésion corporelle externe ; on note une douleur abdominale, une tachypnée superficielle, une tension artérielle basse, une soif intense, des sueurs froides profuses et un bombement du cul-de-sac de Douglas au toucher rectal. Face à ces différents signes, le chirurgien pose le diagnostic de contusion abdominale.\",\n       \"text\": \"Le bilan biologique de Daména comporte les deux examens suivants :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Doppler pulsé\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ionogramme sanguin\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Bilan de l'hémostase\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Acide urique\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Natrémie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Ionogramme sanguin ; C. Bilan de l'hémostase\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Les examens biologiques de la contusion abdominale sont la NFS, le bilan de l'hémostase, l'ionogramme sanguin (avec créatinémie, urémie) et l'amylasémie/lipasémie. Le Doppler pulsé est un examen d'imagerie ; l'acide urique n'est pas demandé. Remarque : La natrémie fait partie de l'ionogramme sanguin ; le sujet retient l'ionogramme complet.\\n\\nSource : licence 2 ide.pdf, Contusions abdominales, Examens biologiques (p. 92-93)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__24\",\n       \"num\": \"25\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Étude de cas N° 2 : Vous recevez Mademoiselle Daména, âgée de 27 ans, pesant 90 kg, victime d'un accident avec collision de deux véhicules. L'examen est sans lésion corporelle externe ; on note une douleur abdominale, une tachypnée superficielle, une tension artérielle basse, une soif intense, des sueurs froides profuses et un bombement du cul-de-sac de Douglas au toucher rectal. Face à ces différents signes, le chirurgien pose le diagnostic de contusion abdominale.\",\n       \"text\": \"La conduite à tenir dans le traitement de Daména a deux buts :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Mettre une sonde urinaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Mise en place d'une sonde naso-gastrique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Réaliser l'hémostase de la région atteinte\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Compenser la perte sanguine\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Prendre une voie veineuse sûre de préférence au cathéter\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Réaliser l'hémostase de la région atteinte ; D. Compenser la perte sanguine\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"En cas de lésions internes graves, la conduite à tenir a pour but de compenser la perte sanguine et de réaliser l'hémostase de la région atteinte (ou de réparer une perforation). Voie veineuse, sonde naso-gastrique et sonde urinaire sont des moyens de réanimation, pas des buts.\\n\\nSource : licence 2 ide.pdf, Contusions abdominales, III. Conduite à tenir, A.2 et B (p. 95-96) Brûlures\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une brûlure du 2e degré atteint :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'épiderme et une partie du derme\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le muscle uniquement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'os\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Seulement l'épiderme\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'épiderme, le derme et l'hypoderme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. L'épiderme et une partie du derme\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La brûlure du 2e degré détruit l'épiderme (superficiel : couche basale respectée) et peut atteindre le derme par endroits (profond). L'atteinte de toutes les couches (épiderme, derme, hypoderme) définit le 3e degré ; muscle et os correspondent aux 5e et 6e degrés (carbonisation).\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE .pdf, Brûlures, 3-1 Classification selon la profondeur (p. 83-84)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel signe est caractéristique d'une brûlure du 2e degré ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Peau intacte\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Escarre noire indolore\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Absence de rougeur\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Peau brûlée superficiellement\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Phlyctènes (cloques)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"E. Phlyctènes (cloques)\",\n       \"answerLetters\": [\n        \"E\"\n       ],\n       \"explanation\": \"Le 2e degré superficiel est caractérisé par la phlyctène : bulle translucide remplie de liquide clair ou rosé. L'escarre noire indolore est le signe du 3e degré ; la rougeur sans décollement correspond au 1er degré.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE .pdf, Brûlures, 5-2 Signes locaux (p. 90)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel élément est essentiel pour évaluer la gravité d'une brûlure ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La couleur des cheveux du patient\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La zone atteinte\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le groupe sanguin\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La taille des mains\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La surface corporelle brûlée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"E. La surface corporelle brûlée\",\n       \"answerLetters\": [\n        \"E\"\n       ],\n       \"explanation\": \"Le premier facteur de gravité cité est la surface corporelle brûlée (évaluée par la règle des 9 de Wallace ou la table de Lund et Browder) ; viennent ensuite la profondeur, la localisation, les lésions et tares associées.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE .pdf, Brûlures, 3-3 Les brûlures graves (p. 85-86) et IV. Critères de gravité (p. 98)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une brûlure du 2e degré superficiel cicatrise généralement en :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Plus de 6 mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"4 semaines\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"10 à 21 jours\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Jamais spontanément\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"1 à 3 jours\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Plus de 6 mois\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours indique que le 2e degré superficiel guérit spontanément, avec une cicatrice de bonne qualité.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE .pdf, Brûlures, 3-1 (p. 84), 5-2 (p. 90) et 4.4 (p. 99)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une brûlure du 2e degré étendue chez un enfant doit conduire à :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Badigeonner la plaie avec du mercurochrome\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une exposition au soleil pour sécher la plaie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une simple surveillance à domicile dans tous les cas\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une évaluation médicale rapide\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Aucun soin particulier\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Une évaluation médicale rapide\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Chez l'enfant, une brûlure est dite étendue dès 5 % de surface corporelle et grave au-delà de 10 % : une brûlure du 2e degré étendue justifie une évaluation médicale rapide (risque de choc hypovolémique). Mercurochrome, soleil ou simple surveillance à domicile sont inadaptés.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE .pdf, Brûlures, 3-2 et 3-3 (p. 85-86)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle complication est fréquente en cas de brûlure du 2e degré ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hypertension artérielle\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Myopie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Otite\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Infection\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Fièvre\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Infection\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'infection est l'une des complications majeures des brûlures : dans la période secondaire (« maladie des brûlés »), les deux phénomènes les plus patents sont l'infection et la dénutrition. La fièvre est un signe de cette infection, pas une complication en soi.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE .pdf, Brûlures, 4-3 Période secondaire (p. 89) et 5-3 (p. 91)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Concernant les cloques, il faut :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les empêcher de rompre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les percer systématiquement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les arracher\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les protéger autant que possible\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Les frotter avec de l'alcool\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Les protéger autant que possible\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La phlyctène est une protection naturelle de la surface brûlée : on ne la perce pas systématiquement, on ne l'arrache pas et on n'y met pas d'alcool ; on la protège (pansement propre) pour limiter le risque d'infection.\\n\\nSource : (explication en partie hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une brûlure du 2e degré profond peut :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Nécessiter une greffe cutanée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Cicatriser seule\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Toucher uniquement l'épiderme\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Guérir en 24 heures\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Ne laisser aucune trace\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Nécessiter une greffe cutanée\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le 2e degré profond cicatrise lentement (15 à 45 jours) avec une cicatrice de mauvaise qualité ; le traitement local vise une cicatrisation rapide des lésions intermédiaires ou un tissu de granulation apte à la greffe, et le recouvrement se fait par greffes (autogreffes). Il ne touche pas seulement l'épiderme et laisse des traces.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE .pdf, Brûlures, 5-2 (p. 90) et traitement local (p. 95)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel est le premier geste recommandé après une brûlure thermique récente ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Appliquer du beurre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Refroidir avec de l'eau tempérée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Mettre de la glace directement sur la brûlure\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'exposer au vent\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Percer les cloques\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Refroidir avec de l'eau tempérée\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Premier secours : refroidissement par l'eau à 15 °C pendant environ 15 minutes, puis retrait des vêtements imbibés et protection par des champs stériles ou draps propres. Beurre, glace directe, exposition au vent et percement des cloques sont à proscrire.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE .pdf, Brûlures, V. Conduite à tenir, 5.1 Premiers secours (p. 100)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La douleur dans une brûlure du 2e degré est généralement :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Très intense\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Absente\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Limitée aux brûlures profondes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Faible\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Lancinante\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Très intense\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans le 2e degré superficiel, la douleur est très vive, lancinante, et devient atroce au contact ; les phlyctènes sont « très douloureuses ». C'est le 3e degré qui est insensible (anesthésie). Remarque : Le cours qualifie aussi la douleur de « lancinante » (option non cochée) ; « très intense » est le caractère retenu.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE .pdf, Brûlures, 5-2 (p. 90) et 4.4 (p. 99)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__35\",\n       \"num\": \"36\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En cas d'appendicite à la fosse iliaque gauche, on parle de situs inversus.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La localisation habituelle de l'appendice est la fosse iliaque droite. Le cours cite l'« appendicite à gauche » parmi les formes topographiques ; elle s'observe notamment en cas de situs inversus (inversion complète des viscères), d'où l'affirmation retenue. Remarque : Une appendicite à gauche peut aussi venir d'un cæcum mobile ou d'un appendice long ; le cours ne cite pas le terme « situs inversus ».\\n\\nSource : licence 2 ide.pdf, Appendicite, Formes topographiques (p. 116) — le lien avec le situs inversus est hors cours du projet\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__36\",\n       \"num\": \"37\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La contention dans la fracture des os de la jambe s'effectue avec un plâtre allant du 1/3 inférieur de la cuisse aux orteils.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : dans la fracture des deux os de la jambe, la contention se fait avec un grand plâtre allant du tiers MOYEN de la cuisse aux orteils, pour immobiliser les articulations suset sous-jacentes (pied à angle droit, genou en légère flexion).\\n\\nSource : licence 2 ide.pdf, Fractures des deux os de la jambe, 6.1 Traitement orthopédique (p. 56)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__37\",\n       \"num\": \"38\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le traitement de l'embarrure consiste à faire une trépanation.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : le traitement de l'embarrure consiste à remonter le fragment enfoncé à son niveau initial et à suturer, sous couverture antibiotique. La trépanation (trou de trépan) sert à évacuer un hématome extra- ou sous-dural.\\n\\nSource : NEUROCHIRURGIE L3.pptx, Traumatismes crâniens, IV. Traitement (diapos 35-38) ; Cours de chirurgie traumatique et digestif.pptx, diapos 116-118\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__38\",\n       \"num\": \"39\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le mécanisme de la fracture du carpe se présente comme une chute sur la paume de la main en hyperextension, et en légère adduction.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : le mécanisme de la fracture du carpe (scaphoïde) est une chute sur la paume de la main en hyperextension et en légère ABDUCTION, pas en adduction.\\n\\nSource : licence 2 ide.pdf, Fractures du poignet, II. Fracture du carpe, 6.5 Mécanisme (p. 41) ; Cours de chirurgie traumatique et digestif.pptx, diapo 61\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__39\",\n       \"num\": \"40\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La désinfection avec un antiseptique est le premier geste dans la chronologie de soins d'une plaie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : la chronologie des soins devant une plaie est : découvrir la plaie, l'inspecter, la désinfecter avec un antiseptique, l'assécher, appliquer le produit indiqué, la recouvrir. La désinfection est donc la 3e étape, pas la première.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE .pdf, Plaies, VI. Conduite à tenir (p. 59)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__40\",\n       \"num\": \"41\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'anthrax est une glomération de furoncles.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours définit l'anthrax comme une agglomération de furoncles reliés entre eux par une suppuration du derme, survenant sur un organisme déficient (diabète surtout).\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE .pdf, Anthrax, I. Définition (p. 41) ; licence 2 ide.pdf, exercice Q28 (p. 218)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__41\",\n       \"num\": \"42\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'appréciation de la gravité d'une brûlure se fait uniquement en fonction de l'étendue de la surface corporelle brûlée.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : la gravité d'une brûlure ne dépend pas seulement de la surface brûlée ; il faut aussi tenir compte de la profondeur, de la localisation (face, mains, plis, périnée), des lésions associées, des tares, de l'âge et des circonstances (durée d'exposition, agent).\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE .pdf, Brûlures, 3-3 et IV. Critères de gravité (p. 85-86, 98-99)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__42\",\n       \"num\": \"43\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En cas de brûlure, les fuites plasmatiques sont aussi responsables de la formation des œdèmes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : la brûlure entraîne une fuite plasmatique massive et brutale (plasmorragie, surtout d'albumine vers le secteur interstitiel) liée aux troubles de la perméabilité capillaire ; c'est elle qui constitue les œdèmes, résorbés vers le 3e-4e jour.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE .pdf, Brûlures, II. Physiopathologie, 2.1-2.2 (p. 96) et 4-2 (p. 88)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__43\",\n       \"num\": \"44\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le scanner abdominal est inutile dans l'évaluation d'une contusion abdominale.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : la tomodensitométrie (scanner) abdominale est un examen performant pour le diagnostic des hémopéritoines et des lésions viscérales et permet un bilan complet ; ses inconvénients sont le coût, la disponibilité et le déplacement du blessé.\\n\\nSource : licence 2 ide.pdf, Contusions abdominales, Examens d'imagerie (p. 93)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__44\",\n       \"num\": \"45\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'absence de douleur élimine une lésion thoracique grave.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : l'absence de douleur n'élimine pas une lésion grave. Même sans signe de souffrance cardio-respiratoire (simple contusion), le cours impose de surveiller le patient car des complications peuvent apparaître ; un blessé peut d'ailleurs être inconscient ou avoir d'autres lésions qui masquent la douleur.\\n\\nSource : licence 2 ide.pdf, Traumatisme du thorax, 2.2.1 (p. 10) — en partie hors cours du projet\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__45\",\n       \"num\": \"46\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'hémothorax correspond à une accumulation de sang dans la cavité thoracique.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours définit l'hémothorax comme un épanchement de sang dans la plèvre (cavité pleurale), qui comprime le poumon. La correction nationale retient « Faux » parce que l'énoncé parle de « cavité thoracique », terme trop large (la cavité thoracique contient aussi le médiastin, le péricarde…). Remarque : Dans le langage courant, l'hémothorax est souvent décrit comme du sang « dans le thorax » ; la réponse se joue sur la précision « plèvre » du cours.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Traumatisme du thorax, diapo 10\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__46\",\n       \"num\": \"47\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un volet thoracique améliore la mécanique respiratoire du patient.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : le volet costal (fragment de côtes isolé par deux traits de fracture, mobile) entraîne une respiration paradoxale : enfoncement à l'inspiration, expulsion à l'expiration, d'où hypoventilation et détresse respiratoire. Il aggrave la mécanique respiratoire.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Traumatisme du thorax, diapos 6-9\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__47\",\n       \"num\": \"48\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Tout traumatisme thoracique avec dyspnée nécessite une évaluation médicale urgente.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : la dyspnée est un signe de souffrance respiratoire (hémothorax, pneumothorax, volet, rupture trachéo-bronchique…). La conduite à tenir en urgence devant toute détresse respiratoire après un traumatisme du thorax comporte libération des voies aériennes, drainage des épanchements et rétablissement de la volémie.\\n\\nSource : licence 2 ide.pdf, Traumatisme du thorax, 2.2.2 et Conduite à tenir en urgence (p. 10-12)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__48\",\n       \"num\": \"49\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans le traumatisme du thorax, à l'auscultation l'on observe une matité.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : la matité se recherche à la PERCUSSION (elle évoque un hémothorax ; l'hypersonorité un pneumothorax). L'auscultation apprécie le murmure vésiculaire (diminué ou aboli) et les bruits du cœur.\\n\\nSource : licence 2 ide.pdf, Traumatisme du thorax, 2.1.3 Auscultation et 2.1.4 Percussion (p. 9)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__49\",\n       \"num\": \"50\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le pied bot varus équin n'atteint uniquement que les garçons.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le pied bot varus équin est le plus fréquent des pieds bots (9/10) ; il atteint SURTOUT les garçons et a souvent un caractère héréditaire et familial.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE .pdf, Pieds bots congénitaux, III. 3.1 Description (p. 81)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__50\",\n       \"num\": \"51\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le pied talus est un pied en hyperflexion, en dehors par rapport à l'axe du corps.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : le pied talus est un pied en hyperflexion DORSALE (pied « piolet » : flexion dorsale exagérée de l'avant-pied et du calcanéum). Le pied dévié en dehors par rapport à l'axe du corps est le pied bot valgus.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE .pdf, Pieds bots congénitaux, II. Variétés (p. 81)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__51\",\n       \"num\": \"52\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En cas de fracture crânienne, l'on observe évidemment une embarrure.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : l'embarrure (enfoncement d'un fragment osseux) n'est qu'un type de lésion possible ; une fracture du crâne peut être une simple fissure (fracture linéaire) sans enfoncement.\\n\\nSource : NEUROCHIRURGIE L3.pptx, Traumatismes crâniens — explication en partie hors cours du projet\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__52\",\n       \"num\": \"53\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'urètre est un conduit unilatéral qui transporte l'urine des reins vers la vessie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : le conduit bilatéral qui transporte l'urine des reins vers la vessie est l'URETÈRE. L'urètre est un conduit unique, canal excréteur de la vessie, qui conduit l'urine de la vessie vers l'extérieur (méat).\\n\\nSource : ANATOMIE LIVRE 2023-2024 OK.pdf, Chap. VI, L'urètre (p. 89) ; licence 2 ide.pdf, Rétrécissement de l'urètre, Généralités (p. 177)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__53\",\n       \"num\": \"54\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'une des complications locales dans l'anthrax est l'adéno-phlegmon.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : les complications locales de l'anthrax circonscrit sont la suppuration péri- ou sous-anthracoïde, la lymphangite réticulaire, l'adénite et l'adéno-phlegmon (les complications générales étant septicémie, métastase suppurée, anthrax diffus ou gangreneux).\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE .pdf, Anthrax, 4- Les complications (p. 43)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j6-ide__54\",\n       \"num\": \"55\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La crépitation neigeuse est un signe physique de la gangrène gazeuse.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : à la palpation, une sensation de crépitation neigeuse sous-cutanée traduit l'emphysème (gaz produits par les germes anaérobies) ; elle s'étend à la période d'extension.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE .pdf, Gangrène gazeuse, IV. Signes cliniques, 4.1 b et 4.2 (p. 48-49)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J6 (IDE)\",\n       \"sourceFile\": \"J6_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
